{
	"name": "@sessionwise/opencode-plugin",
	"version": "0.1.0",
	"description": "SessionWise plugin for opencode — captures tool usage and chat messages into the SessionWise knowledge base via the local sessionwise CLI.",
	"type": "module",
	"main": "./dist/index.js",
	"module": "./dist/index.js",
	"types": "./dist/index.d.ts",
	"exports": {
		".": {
			"types": "./dist/index.d.ts",
			"import": "./dist/index.js"
		}
	},
	"files": [
		"dist",
		"README.md",
		"LICENSE"
	],
	"keywords": [
		"opencode",
		"opencode-plugin",
		"sessionwise",
		"ai-coding",
		"session-tracking"
	],
	"homepage": "https://sessionwise.dev",
	"repository": {
		"type": "git",
		"url": "git+https://github.com/norbertbanaszek/sessionwise.git",
		"directory": "packages/opencode-plugin"
	},
	"license": "MIT",
	"author": "SessionWise",
	"publishConfig": {
		"access": "public"
	},
	"peerDependencies": {
		"@opencode-ai/plugin": ">=1.0.0"
	},
	"peerDependenciesMeta": {
		"@opencode-ai/plugin": {
			"optional": true
		}
	},
	"devDependencies": {
		"@opencode-ai/plugin": "^1.14.22",
		"@types/node": "^22.10.0",
		"@vitest/coverage-v8": "^3.2.4",
		"tsup": "^8.4.0",
		"typescript": "^5.7.3",
		"vitest": "^3.1.1"
	},
	"scripts": {
		"build": "tsup",
		"dev": "tsup --watch",
		"test": "vitest run",
		"test:coverage": "vitest run --coverage",
		"clean": "rm -rf dist"
	},
	"engines": {
		"node": ">=18"
	}
}
